_make_completion { local cur prev COMPREPLY= cur="${COMP_WORDS[COMP_CWORD]}" prev="${COMP_WORDS[COMP_CWORD-1]}" if [[ ${COMP_CWORD} -eq 1 ]]; then # Complete make targets COMPREPLY=($(compgen -W "$(make -pq 2>/dev/null | awk -F':' '/^[a-zA-Z0-9][^$#\/\t=]*:([^=]|$)/ {split($1,A,/);for(i in A)print A[i]}' | sort -u)" -- "$cur")) elif [[ ${prev} == "run-a" || ${prev} == "run-b" || ${prev} == "run-local" ]]; then # Complete with app names from build/bin/ if [[ -d "build/bin" ]]; then COMPREPLY=($(compgen -W "$(ls build/bin/ 2>/dev/null)" -- "$cur")) fi fi
} complete -F _make_completion make